let snapshot = flow.get('greenhouse_snapshot') || getInitialSnapshot();
let history = flow.get('telemetry_history') || { bed_a: [], bed_b: [], climate: [], utility: [] };

const topic = msg.topic;
const parts = topic.split('/');
const nodeId = parts[1];
const data = msg.payload;

if (snapshot.nodes[nodeId]) {
    snapshot.nodes[nodeId].analog_value = parseFloat(data.analog) || 0;
    snapshot.nodes[nodeId].digital_value = data.digital !== undefined ? data.digital : 0;
    if (data.output !== undefined) snapshot.nodes[nodeId].output_state = data.output;
    snapshot.nodes[nodeId].seq = data.seq || 0;
    snapshot.nodes[nodeId].online = true;
    snapshot.nodes[nodeId].last_seen = new Date().toISOString();
}

// Update Water Low
if (nodeId === 'utility') {
    snapshot.water_low = (data.digital === 1);
    snapshot.emergency = snapshot.water_low;
}

// Save Telemetry Point
const point = {
    node_id: nodeId,
    analog: parseFloat(data.analog) || 0,
    digital: data.digital || 0,
    output: data.output || 0,
    timestamp: new Date().toISOString()
};

if (!history[nodeId]) history[nodeId] = [];
history[nodeId].push(point);
if (history[nodeId].length > 40) history[nodeId].shift();

flow.set('greenhouse_snapshot', snapshot);
flow.set('telemetry_history', history);

// Broadcast WS Node Update & Telemetry Point
const wsNodeMsg = { payload: JSON.stringify({ type: 'node', data: snapshot.nodes[nodeId] }) };
const wsPointMsg = { payload: JSON.stringify({ type: 'telemetry', data: point }) };

return [[wsNodeMsg, wsPointMsg]];

