let snapshot = flow.get('greenhouse_snapshot');
if (!snapshot) return null;

const data = msg.payload;
const actType = data.type || (msg.topic.split('/')[2]);

if (snapshot.actuators[actType]) {
    snapshot.actuators[actType].coil = data.coil !== undefined ? data.coil : snapshot.actuators[actType].coil;
    snapshot.actuators[actType].running = data.running !== undefined ? data.running : data.coil;
