let snapshot = flow.get('greenhouse_snapshot') || {};
let cfg = snapshot.config || {
    auto_mode: true,
    moisture_a_min: 35.0,
    moisture_a_max: 45.0,
    moisture_b_min: 35.0,
    moisture_b_max: 45.0,
    temp_high: 32.0,
    temp_low: 30.0,
    light_min: 30.0,
    light_max: 40.0
};

const topic = msg.topic;
const data = msg.payload;
const parts = topic.split('/');
const nodeId = parts[1];

let commandMessages = [];
let modbusMessages = [];

// 1. Emergency Water Low check
if (nodeId === 'utility' && data.digital === 1) {
    const valveA = snapshot.nodes.bed_a ? snapshot.nodes.bed_a.output_state : 0;
    const valveB = snapshot.nodes.bed_b ? snapshot.nodes.bed_b.output_state : 0;
    const pumpCoil = snapshot.actuators.pump ? snapshot.actuators.pump.coil : 0;
    if (pumpCoil === 1) {
        commandMessages.push({ topic: 'greenhouse/actuator/pump/command', payload: { command: 'SET_COIL', coil: 0 } });
        modbusMessages.push({ payload: { value: false, unitid: 1, fc: 5, address: 0 } });
    }
    if (valveA === 1) {
        commandMessages.push({ topic: 'greenhouse/bed_a/command', payload: { command_id: Date.now(), output: 0 } });
    }
    if (valveB === 1) {
        commandMessages.push({ topic: 'greenhouse/bed_b/command', payload: { command_id: Date.now(), output: 0 } });
    }
    if (!snapshot.water_low) {
        commandMessages.push({ topic: 'greenhouse/alerts', payload: { level: 'DANGER', source: 'utility', message: '🚨 น้ำในถังต่ำ! หยุดปั๊มน้ำและปิดวาล์ว A/B ทั้งหมดทันที' } });
    }
    return [commandMessages, modbusMessages];
}

if (!cfg.auto_mode) return null;

// 2. Bed A Moisture
if (nodeId === 'bed_a') {
    const moisture = data.analog;
    const pot = data.digital === 1;
    const valveA = snapshot.nodes.bed_a ? snapshot.nodes.bed_a.output_state : 0;
    const isOverridden = snapshot.nodes.bed_a && snapshot.nodes.bed_a.manual_override_until > Date.now();
    if (!isOverridden) {
        if (moisture < cfg.moisture_a_min && pot && valveA === 0 && !snapshot.water_low) {
            commandMessages.push({ topic: 'greenhouse/bed_a/command', payload: { command_id: Date.now(), output: 1 } });
            commandMessages.push({ topic: 'greenhouse/actuator/pump/command', payload: { command: 'SET_COIL', coil: 1 } });
            modbusMessages.push({ payload: { value: true, unitid: 1, fc: 5, address: 0 } });
        } else if ((moisture > cfg.moisture_a_max || !pot) && valveA === 1) {
            commandMessages.push({ topic: 'greenhouse/bed_a/command', payload: { command_id: Date.now(), output: 0 } });
            // Check if Bed B is also closed
            const valveB = snapshot.nodes.bed_b ? snapshot.nodes.bed_b.output_state : 0;
            if (valveB === 0) {
                commandMessages.push({ topic: 'greenhouse/actuator/pump/command', payload: { command: 'SET_COIL', coil: 0 } });
                modbusMessages.push({ payload: { value: false, unitid: 1, fc: 5, address: 0 } });
            }
        }
    }
}

// 3. Bed B Moisture
if (nodeId === 'bed_b') {
    const moisture = data.analog;
    const pot = data.digital === 1;
    const valveB = snapshot.nodes.bed_b ? snapshot.nodes.bed_b.output_state : 0;
    const isOverridden = snapshot.nodes.bed_b && snapshot.nodes.bed_b.manual_override_until > Date.now();
    if (!isOverridden) {
        if (moisture < cfg.moisture_b_min && pot && valveB === 0 && !snapshot.water_low) {
            commandMessages.push({ topic: 'greenhouse/bed_b/command', payload: { command_id: Date.now(), output: 1 } });
            commandMessages.push({ topic: 'greenhouse/actuator/pump/command', payload: { command: 'SET_COIL', coil: 1 } });
            modbusMessages.push({ payload: { value: true, unitid: 1, fc: 5, address: 0 } });
        } else if ((moisture > cfg.moisture_b_max || !pot) && valveB === 1) {
            commandMessages.push({ topic: 'greenhouse/bed_b/command', payload: { command_id: Date.now(), output: 0 } });
            const valveA = snapshot.nodes.bed_a ? snapshot.nodes.bed_a.output_state : 0;
            if (valveA === 0) {
                commandMessages.push({ topic: 'greenhouse/actuator/pump/command', payload: { command: 'SET_COIL', coil: 0 } });
                modbusMessages.push({ payload: { value: false, unitid: 1, fc: 5, address: 0 } });
            }
        }
    }
}

// 4. Climate Temperature
if (nodeId === 'climate') {
    const temp = data.analog;
    const fanReq = data.digital === 1;
    const fanState = snapshot.nodes.climate ? snapshot.nodes.climate.output_state : 0;
    if (fanReq || temp > cfg.temp_high) {
        if (fanState === 0) {
            commandMessages.push({ topic: 'greenhouse/climate/command', payload: { command_id: Date.now(), output: 1 } });
            commandMessages.push({ topic: 'greenhouse/actuator/fan/command', payload: { command: 'SET_COIL', coil: 1 } });
            modbusMessages.push({ payload: { value: true, unitid: 2, fc: 5, address: 0 } });
        }
    } else if (temp < cfg.temp_low && fanState === 1 && !fanReq) {
        commandMessages.push({ topic: 'greenhouse/climate/command', payload: { command_id: Date.now(), output: 0 } });
        commandMessages.push({ topic: 'greenhouse/actuator/fan/command', payload: { command: 'SET_COIL', coil: 0 } });
        modbusMessages.push({ payload: { value: false, unitid: 2, fc: 5, address: 0 } });
    }
}

// 5. Utility Light
if (nodeId === 'utility') {
    const light = data.analog;
    const lightState = snapshot.nodes.utility ? snapshot.nodes.utility.output_state : 0;
    if (light < cfg.light_min && lightState === 0) {
        commandMessages.push({ topic: 'greenhouse/utility/command', payload: { command_id: Date.now(), output: 1 } });
        commandMessages.push({ topic: 'greenhouse/actuator/light/command', payload: { command: 'SET_COIL', coil: 1 } });
        modbusMessages.push({ payload: { value: true, unitid: 3, fc: 5, address: 0 } });
    } else if (light > cfg.light_max && lightState === 1) {
        commandMessages.push({ topic: 'greenhouse/utility/command', payload: { command_id: Date.now(), output: 0 } });
        commandMessages.push({ topic: 'greenhouse/actuator/light/command', payload: { command: 'SET_COIL', coil: 0 } });
        modbusMessages.push({ payload: { value: false, unitid: 3, fc: 5, address: 0 } });
    }
}

return [commandMessages, modbusMessages];

try {
    const payload = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (payload.type === 'command') {
        msg.payload = payload;
        return [msg];
    }
} catch (e) {}
return null;

let snapshot = flow.get('greenhouse_snapshot');
if (!snapshot) {
    snapshot = {
        config: { auto_mode: true, moisture_a_min: 35.0, moisture_a_max: 45.0, moisture_b_min: 35.0, moisture_b_max: 45.0, temp_high: 32.0, temp_low: 30.0, light_min: 30.0, light_max: 40.0, last_modified: new Date().toISOString() },
        nodes: {
            bed_a: { id: 'bed_a', name: 'แปลงผัก A (Bed A)', description: 'ESP32 #1 - ความชื้นดินและวาล์ว A', analog_label: 'ความชื้นดิน', analog_unit: '%', analog_value: 0.0, digital_label: 'มีกระถางผัก', digital_value: 1, output_label: 'วาล์วน้ำ A', output_state: 0, seq: 0, online: true, last_seen: new Date().toISOString() },
            bed_b: { id: 'bed_b', name: 'แปลงผัก B (Bed B)', description: 'ESP32 #2 - ความชื้นดินและวาล์ว B', analog_label: 'ความชื้นดิน', analog_unit: '%', analog_value: 0.0, digital_label: 'มีกระถางผัก', digital_value: 1, output_label: 'วาล์วน้ำ B', output_state: 0, seq: 0, online: true, last_seen: new Date().toISOString() },
            climate: { id: 'climate', name: 'สภาพอากาศ (Climate)', description: 'ESP32 #3 - อุณหภูมิและพัดลม', analog_label: 'อุณหภูมิ', analog_unit: '°C', analog_value: 0.0, digital_label: 'ปุ่มขอเปิดพัดลม', digital_value: 0, output_label: 'พัดลมระบายอากาศ', output_state: 0, seq: 0, online: true, last_seen: new Date().toISOString() },
            utility: { id: 'utility', name: 'ระบบส่วนกลางและแสง (Utility)', description: 'ESP32 #4 - แสง ระดับน้ำ และไฟปลูก', analog_label: 'ความเข้มแสง', analog_unit: '%', analog_value: 0.0, digital_label: 'ระดับน้ำต่ำ', digital_value: 0, output_label: 'โคมไฟปลูกพืช', output_state: 0, seq: 0, online: true, last_seen: new Date().toISOString() }
        },
        actuators: {
            pump: { id: 'pump', slave_id: 1, type: 'pump', name: 'ปั๊มน้ำหลัก (Pump Station)', coil: 0, mode: 1, target: 15, running: 0, simulated_value: 0, last_updated: new Date().toISOString() },
            fan: { id: 'fan', slave_id: 2, type: 'fan', name: 'พัดลมระบายอากาศ (Exhaust Fan)', coil: 0, mode: 1, target: 30, running: 0, simulated_value: 0, last_updated: new Date().toISOString() },
            light: { id: 'light', slave_id: 3, type: 'light', name: 'โคมไฟปลูกพืช (Grow Light)', coil: 0, mode: 1, target: 40, running: 0, simulated_value: 0, last_updated: new Date().toISOString() }
        },
        recent_events: [],
        water_low: false,
        emergency: false,
        server_time: new Date().toISOString()
    };
    flow.set('greenhouse_snapshot', snapshot);
}
snapshot.server_time = new Date().toISOString();
msg.payload = snapshot;
return msg;

let snapshot = flow.get('greenhouse_snapshot') || { nodes: {} };
msg.payload = Object.values(snapshot.nodes);
return msg;

let history = flow.get('telemetry_history') || {};
const nodeId = msg.req.query.node_id;
const limit = parseInt(msg.req.query.limit) || 40;

if (nodeId && history[nodeId]) {
    msg.payload = history[nodeId].slice(-limit);
} else {
    let combined = [];
    for (const id in history) combined = combined.concat(history[id]);
    msg.payload = combined.slice(-limit);
}
return msg;

let snapshot = flow.get('greenhouse_snapshot') || { recent_events: [] };
msg.payload = snapshot.recent_events || [];
return msg;

const cmd = msg.payload;
let mqttMsgs = [];
let modbusMsgs = [];
let snapshot = flow.get('greenhouse_snapshot');

if (cmd.target_type === 'actuator') {
    const actType = cmd.target_id; // pump, fan, light
    let slaveId = 1;
    if (actType === 'fan') slaveId = 2;
    if (actType === 'light') slaveId = 3;

    const coil = cmd.output !== undefined ? cmd.output : 1;
    if (snapshot && snapshot.actuators[actType]) {
        snapshot.actuators[actType].coil = coil;
        snapshot.actuators[actType].running = coil;
    }
    mqttMsgs.push({
        topic: 'greenhouse/actuator/' + actType + '/command',
        payload: { command: 'SET_COIL', coil: coil, mode: cmd.mode || 0 }
    });
    modbusMsgs.push({
        payload: { value: (coil === 1), unitid: slaveId, fc: 5, address: 0 }
    });
} else {
    const nodeId = cmd.target_id;
    if (nodeId === 'water_low') {
        const isLow = (cmd.output === 1);
        if (snapshot) {
            snapshot.water_low = isLow;
            snapshot.emergency = isLow;
        }
        mqttMsgs.push({
            topic: 'greenhouse/utility/command',
            payload: { command_id: Date.now(), target: 'water_low', output: cmd.output }
        });
    } else {
        if (snapshot && snapshot.nodes[nodeId]) {
            snapshot.nodes[nodeId].output_state = cmd.output;
            snapshot.nodes[nodeId].manual_override_until = Date.now() + 30000;
        }
        mqttMsgs.push({
            topic: 'greenhouse/' + nodeId + '/command',
            payload: { command_id: Date.now(), output: cmd.output }
        });
    }
}
if (snapshot) flow.set('greenhouse_snapshot', snapshot);

// Respond to HTTP request
const respMsg = {
    req: msg.req,
    res: msg.res,
    payload: {
        success: true,
        message: 'Command dispatched successfully',
        command_id: Date.now(),
        timestamp: new Date().toISOString()
    }
};

return [respMsg, mqttMsgs, modbusMsgs];

let snapshot = flow.get('greenhouse_snapshot');
if (!snapshot) return null;

const newCfg = msg.payload;
for (const k in newCfg) {
    if (snapshot.config[k] !== undefined) {
        snapshot.config[k] = newCfg[k];
    }
}
snapshot.config.last_modified = new Date().toISOString();
flow.set('greenhouse_snapshot', snapshot);

// Publish updated config to MQTT
const mqttMsg = {
    topic: 'greenhouse/system/config',
    payload: snapshot.config
};

// Broadcast WS Config update
const wsMsg = {
    payload: JSON.stringify({ type: 'config', data: snapshot.config })
};

const respMsg = {
    req: msg.req,
    res: msg.res,
    payload: {
        success: true,
        config: snapshot.config
    }
};

return [respMsg, mqttMsg, wsMsg];

let pollIdx = context.get('poll_idx') || 1;

const msgOut = {
    payload: {
        value: null,
        unitid: pollIdx,
        fc: 4,
        address: 0,
        quantity: 2
    },
    slaveId: pollIdx
};

pollIdx++;
if (pollIdx > 3) pollIdx = 1;
context.set('poll_idx', pollIdx);

return msgOut;

const slaveId = msg.slaveId || (msg.modbusRequest ? msg.modbusRequest.unitid : 1);
const data = msg.payload;

if (!Array.isArray(data) || data.length < 2) {
    return null;
}

let actType = 'pump';
if (slaveId === 2) actType = 'fan';
if (slaveId === 3) actType = 'light';

const running = data[0];
const telemetryVal = data[1];

const stateMsg = {
    topic: 'greenhouse/actuator/' + actType + '/state',
    payload: {
        slave_id: slaveId,
        type: actType,
        coil: running,
        mode: 1,
        target: (actType === 'fan' ? 30 : (actType === 'light' ? 50 : 0)),
        running: running,
        value: telemetryVal
    }
};

return stateMsg;

let snapshot = flow.get('greenhouse_snapshot');
if (!snapshot || !snapshot.nodes) return null;

const now = Date.now();
let updated = false;

for (const id in snapshot.nodes) {
    const node = snapshot.nodes[id];
    const lastSeenTime = Date.parse(node.last_seen);
    if (node.online && (now - lastSeenTime > 15000)) {
        node.online = false;
        updated = true;
    }
}

if (updated) {
    flow.set('greenhouse_snapshot', snapshot);
    return { payload: JSON.stringify({ type: 'snapshot', data: snapshot }) };
}
return null;
